-- Run once in Supabase SQL Editor. Authentication: create users in Authentication > Users.
create table if not exists public.tanks(id integer generated by default as identity primary key,slug text unique not null,name text not null,stock numeric(12,2) not null check(stock>=0),meter numeric(12,2) not null check(meter>=0));
insert into public.tanks(id,slug,name,stock,meter) values (1,'doppelachser','Doppelachser',280,12450),(2,'einachser','Einachser',850,50200) on conflict(id) do nothing;
select setval(pg_get_serial_sequence('public.tanks','id'),(select max(id) from public.tanks));
create table if not exists public.operators(id bigint generated always as identity primary key,name text not null unique,created_at timestamptz not null default now());
create table if not exists public.transactions(id bigint generated always as identity primary key,created_at timestamptz not null default now(),type text not null check(type in ('fuel','refill')),tank_id integer not null references public.tanks(id),tank_name text not null,operator text not null,aircraft text,amount numeric(12,2) not null check(amount>0),old_stock numeric(12,2) not null,new_stock numeric(12,2) not null check(new_stock>=0),old_meter numeric(12,2),new_meter numeric(12,2),calculated_stock numeric(12,2),corrected boolean not null default false,created_by uuid not null references auth.users(id));
alter table public.tanks enable row level security;alter table public.operators enable row level security;alter table public.transactions enable row level security;
create policy "signed in read tanks" on public.tanks for select to authenticated using(true);
create policy "signed in read operators" on public.operators for select to authenticated using(true);
create policy "signed in read transactions" on public.transactions for select to authenticated using(true);
-- Do not create public write policies: all writes go through a controlled database function or server-side Edge Function.
create or replace function public.record_fueling(p_tank_id integer,p_operator text,p_aircraft text,p_new_meter numeric) returns bigint language plpgsql security definer set search_path=public as $$
declare t public.tanks%rowtype; qty numeric(12,2); result_id bigint; who uuid:=auth.uid();
begin
 if who is null then raise exception 'Anmeldung erforderlich';end if;
 if length(trim(coalesce(p_operator,'')))<1 or length(trim(coalesce(p_aircraft,'')))<1 then raise exception 'Name und Rufzeichen erforderlich';end if;
 if p_new_meter is null or p_new_meter<0 then raise exception 'Ungültiger Zählerstand';end if;
 select * into t from public.tanks where id=p_tank_id for update;
 if not found then raise exception 'Tank nicht gefunden';end if;
 qty:=p_new_meter-t.meter;
 if qty<=0 or qty>t.stock then raise exception 'Zählerstand oder Bestand ungültig';end if;
 update public.tanks set stock=stock-qty,meter=p_new_meter where id=t.id;
 insert into public.operators(name) values(trim(p_operator)) on conflict(name) do nothing;
 insert into public.transactions(type,tank_id,tank_name,operator,aircraft,amount,old_stock,new_stock,old_meter,new_meter,created_by) values('fuel',t.id,t.name,trim(p_operator),upper(trim(p_aircraft)),qty,t.stock,t.stock-qty,t.meter,p_new_meter,who) returning id into result_id;
 return result_id;
end $$;
revoke all on function public.record_fueling(integer,text,text,numeric) from public,anon;
grant execute on function public.record_fueling(integer,text,text,numeric) to authenticated;
-- Refill writes are exclusively in Edge Function with service-role access, never from the client.
create or replace function public.record_refill_internal(p_tank_id integer,p_operator text,p_amount numeric,p_corrected_stock numeric,p_user_id uuid) returns bigint language plpgsql security definer set search_path=public as $$
declare t public.tanks%rowtype; calculated numeric(12,2); final_stock numeric(12,2); result_id bigint;
begin
 if p_user_id is null or not exists(select 1 from auth.users where id=p_user_id) then raise exception 'Ungültiger Benutzer';end if;
 if length(trim(coalesce(p_operator,'')))<1 or p_amount is null or p_amount<=0 then raise exception 'Ungültige Auffüllung';end if;
 select * into t from public.tanks where id=p_tank_id for update;
 if not found then raise exception 'Tank nicht gefunden';end if;
 calculated:=t.stock+p_amount;final_stock:=coalesce(p_corrected_stock,calculated);
 if final_stock<0 then raise exception 'Bestand darf nicht negativ sein';end if;
 update public.tanks set stock=final_stock where id=t.id;
 insert into public.operators(name) values(trim(p_operator)) on conflict(name) do nothing;
 insert into public.transactions(type,tank_id,tank_name,operator,amount,old_stock,new_stock,calculated_stock,corrected,created_by) values('refill',t.id,t.name,trim(p_operator),p_amount,t.stock,final_stock,calculated,p_corrected_stock is not null,p_user_id) returning id into result_id;
 return result_id;
end $$;
revoke all on function public.record_refill_internal(integer,text,numeric,numeric,uuid) from public,anon,authenticated;
grant execute on function public.record_refill_internal(integer,text,numeric,numeric,uuid) to service_role;
